{"content":"import { workflow, node, trigger } from '@n8n/workflow-sdk';

const notion_Trigger = trigger({
  type: 'n8n-nodes-base.notionTrigger',
  version: 1,
  config: { name: 'Notion Trigger', parameters: { pollTimes: { item: [{ mode: 'everyMinute' }] } }, position: [0, 0] }
});

const build_blocks = node({
  type: 'n8n-nodes-base.code',
  config: {
    name: 'Build Transcript Blocks',
    parameters: { jsCode: `const lines = $json.text.split(/
/);
return lines.map(line => ({ json: { line } }));` },
    position: [176, 0]
  }
});

const wf = workflow('wf_example_0001', 'My workflow', { executionOrder: 'v1' });
export default wf.add(notion_Trigger).to(build_blocks);
